type SoftDeleteCustomerParams struct {
	ID        string
	DeletedAt pgtype.Timestamptz
}

func (q *Queries) SoftDeleteCustomer(ctx context.Context, arg SoftDeleteCustomerParams) (string, error) {
	row := q.db.QueryRow(ctx, softDeleteCustomer, arg.ID, arg.DeletedAt)
	var id string
	err := row.Scan(&id)
	return id, err
}

const updateCustomer = `-- name: UpdateCustomer :one
UPDATE customer SET
    email      = COALESCE($1::text, email),
    first_name = COALESCE($2::text, first_name),
    last_name  = COALESCE($3::text, last_name),
    phone      = COALESCE($4::text, phone),
    metadata   = COALESCE($5::jsonb, metadata),
    updated_at = $6
WHERE id = $7 AND deleted_at IS NULL
RETURNING id, email, first_name, last_name, phone, has_account, metadata, created_at, updated_at, deleted_at
`

type UpdateCustomerParams struct {
	Email     *string
	FirstName *string
	LastName  *string
	Phone     *string
	Metadata  []byte
	UpdatedAt pgtype.Timestamptz
	ID        string
}

// UpdateCustomer verilmeyen alanları OLDUĞU GİBİ bırakır.
//
// COALESCE ile yazılan bu kısmi güncelleme, "alan gönderilmedi" ile "alan boşa
// çekildi" ayrımını korur: NULL parametre eski değeri saklar, boş dize gerçek
// bir temizlemedir.
func (q *Queries) UpdateCustomer(ctx context.Context, arg UpdateCustomerParams) (Customer, error) {
	row := q.db.QueryRow(ctx, updateCustomer,
		arg.Email,
		arg.FirstName,
		arg.LastName,
		arg.Phone,
		arg.Metadata,
		arg.UpdatedAt,
		arg.ID,
	)
	var i Customer
	err := row.Scan(
		&i.ID,
		&i.Email,
		&i.FirstName,
		&i.LastName,
		&i.Phone,
		&i.HasAccount,
		&i.Metadata,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
	)
	return i, err
}
